/** Where the processed copies live. Generated by `npm run certificates`. */
export const thumbPath = (slug: string) => `/certificates/thumbs/${slug}.webp`;

const ORIGINAL_EXT: Record<string, string> = {
  'google-cybersecurity-professional-certificate': 'pdf',
};

export const filePath = (slug: string) =>
  `/certificates/files/${slug}.${ORIGINAL_EXT[slug] ?? 'pdf'}`;

export const featuredCredentials = credentials.filter((c) => c.featured);

/**
 * What the hero stats bar counts. Every individually verifiable credential:
 * the program badge plus each of its eight course certificates, plus the
 * standalone ones. The Navriti letter is proof of employment, not a
 * credential, so it is excluded.
 */
export const credentialCount = credentials.reduce((total, credential) => {
  if (credential.type === 'letter') return total;
  return total + 1 + (credential.courses?.length ?? 0);
}, 0);

export const categories: CredentialCategory[] = [
  'cloud',
  'security-operations',
  'cybersecurity-foundations',
  'development',
];
